// Writes prisma/schema.postgres.prisma: the same data model as prisma/schema.prisma,
// with the database switched from SQLite (development) to PostgreSQL (production).
// There is one source of truth for the tables; this file is generated, never edited.
const fs = require('fs');
const path = require('path');

const prismaDir = path.join(__dirname, '..', 'prisma');
const SOURCE = path.join(prismaDir, 'schema.prisma');
const TARGET = path.join(prismaDir, 'schema.postgres.prisma');

function toPostgresSchema(schema) {
  const converted = schema.replace(/provider\s*=\s*"sqlite"/, 'provider = "postgresql"');
  if (converted === schema) {
    throw new Error('Expected the datasource in schema.prisma to use provider = "sqlite"');
  }
  return `// GENERATED by scripts/preparePostgres.js from schema.prisma - do not edit.\n${converted}`;
}

function writePostgresSchema() {
  fs.writeFileSync(TARGET, toPostgresSchema(fs.readFileSync(SOURCE, 'utf8')));
  return TARGET;
}

if (require.main === module) {
  console.log(`Wrote ${path.relative(process.cwd(), writePostgresSchema())}`);
}

module.exports = { toPostgresSchema, writePostgresSchema, POSTGRES_SCHEMA_PATH: TARGET };
